"""Behavioral contract tests for the accepted in-memory registry contract.

These tests encode the release specification in docs/contract.md: publication
only expands the shared version collection, while adoption is an explicit
per-usage operation that preserves local retry configuration and rejects
invalid requests before changing caller-owned state.
"""

import unittest

from src.registry import adopt, publish


class PublishTests(unittest.TestCase):
    """Publication records released versions without changing customer uses."""

    def test_publish_adds_version_to_existing_set(self):
        versions = {"v1"}

        publish(versions, "v2")

        self.assertEqual(versions, {"v1", "v2"})

    def test_publish_does_not_mutate_usages_because_adoption_is_explicit(self):
        """Publishing a version must not implicitly move any pinned usage."""
        versions = {"v1"}
        usages = {
            "tile-home": {"version": "v1", "retry_limit": 2},
            "job-nightly": {"version": "v1", "retry_limit": 5},
        }

        publish(versions, "v2")

        self.assertEqual(usages["tile-home"]["version"], "v1")
        self.assertEqual(usages["job-nightly"]["version"], "v1")


class AdoptTests(unittest.TestCase):
    """Adoption pins one known usage to one published version."""

    def test_adopt_updates_only_the_selected_usage_version(self):
        """Different usages keep independent retry limits during adoption."""
        versions = {"v1", "v2"}
        usages = {
            "tile-home": {"version": "v1", "retry_limit": 2},
            "job-nightly": {"version": "v1", "retry_limit": 5},
        }

        adopt(usages, "job-nightly", "v2", versions)

        self.assertEqual(usages["tile-home"], {"version": "v1", "retry_limit": 2})
        self.assertEqual(usages["job-nightly"], {"version": "v2", "retry_limit": 5})

    def test_adopt_rejects_unknown_usage_before_mutation(self):
        versions = {"v1", "v2"}
        usages = {
            "tile-home": {"version": "v1", "retry_limit": 2},
            "job-nightly": {"version": "v1", "retry_limit": 5},
        }
        original_usages = {
            usage_id: usage.copy() for usage_id, usage in usages.items()
        }
        original_versions = versions.copy()

        with self.assertRaises(ValueError):
            adopt(usages, "missing", "v2", versions)

        self.assertEqual(usages, original_usages)
        self.assertEqual(versions, original_versions)

    def test_adopt_rejects_unpublished_version_before_mutation(self):
        versions = {"v1"}
        usages = {
            "tile-home": {"version": "v1", "retry_limit": 2},
            "job-nightly": {"version": "v1", "retry_limit": 5},
        }
        original_usages = {
            usage_id: usage.copy() for usage_id, usage in usages.items()
        }
        original_versions = versions.copy()

        with self.assertRaises(ValueError):
            adopt(usages, "tile-home", "v2", versions)

        self.assertEqual(usages, original_usages)
        self.assertEqual(versions, original_versions)


if __name__ == "__main__":
    unittest.main()
